    k2[i] = f(x[i] + k1[i] * h/2.0, t + h/2.0)[i];
}
std::vector<double> k3 = f(x, t + h/2.0);
for (size_t i = 0; i < x.size(); i++) {
    k3[i] = f(x[i] + k2[i] * h/2.0, t + h/2.0)[i];
}
std::vector<double> k4 = f(x, t + h);
for (size_t i = 0; i < x.size(); i++) {
    k4[i] = f(x[i] + k3[i] * h, t + h)[i];
}
std::vector<double> result(x.size());
for (size_t i = 0; i < x.size(); i++) {
    result[i] = x[i] + (k1[i] + 2.0 * k2[i] + 2.0 * k3[i] + k4[i]) * h/6.0;
}
return result;

